# fixed length / merge / pick / shift / concatenate
check("mfle", mne.make_fixed_length_events(raw, id=3, duration=1.5))
check("mfle2", mne.make_fixed_length_events(raw, start=1.0, stop=8.0, duration=2.0, overlap=0.5))
check("mfle3", mne.make_fixed_length_events(raw, duration=3.0, first_samp=False))
ev = mne.find_events(raw, stim_channel="STI")
check("merge", mne.merge_events(ev, [1, 2], 12))
check("merge_keep", mne.merge_events(ev, [3, 4], 34, replace_events=False))
check("pick_inc", mne.pick_events(ev, include=[1, 4]))
check("pick_exc", mne.pick_events(ev, exclude=2))
